-- 18Birdies — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = '18birdies.com' OR LOWER(`name`) = LOWER('18Birdies'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT '18Birdies', NULL, 'https://18birdies.com', NULL, NULL, 'Застосунок для гольфу: точні GPS-дистанції на полі, електронна картка рахунку, статистика й гандикап, ігри та змагання з друзями, понад 40 000 полів і аналізатор замаху зі штучним інтелектом, який працює як особистий тренер.', 'A golf app: accurate GPS distances on the course, a digital scorecard, stats and handicap, games and competitions with friends, over 40,000 courses and an AI swing analyzer that works like a personal coach.', '18Birdies збирає в одному застосунку все, що потрібно гольфісту на полі. GPS-далекомір показує точні дистанції, а електронна картка допомагає легко вести рахунок, статистику й обчислювати гандикап. Можна об''єднувати раунди з друзями, вести рахунок разом наживо, навіть якщо ви граєте окремо, і дивитися турнірну таблицю. Застосунок автоматично підбиває результати ігор із друзями — доступні до десяти форматів, зокрема Skins, Wolf, Match Play, Nassau та інші. AI-аналізатор замаху й тренер допомагають розібрати техніку й працювати над покращенням гри. У базі понад 40 000 полів із попереднім переглядом GPS-карти, картки рахунку, відгуків і фото. Є турніри, навчальні матеріали та преміум-підписка; почати можна безкоштовно.', '18Birdies brings everything a golfer needs on the course into one app. The GPS rangefinder gives accurate distances, and the digital scorecard makes it easy to keep score, track stats and calculate your handicap. You can connect rounds with friends, score live together even when you''re not playing in the same group, and check the leaderboard. The app automatically tracks the results of games with friends in up to ten formats, including Skins, Wolf, Match Play, Nassau and more. The AI swing analyzer and coach help break down your technique and work on improving your game. The database covers over 40,000 courses with a preview of the GPS map, scorecard, reviews and photos. There are tournaments, learning content and a premium subscription; you can start for free.', 'GPS-дистанції й далекомір
Електронна картка рахунку й гандикап
Статистика гри
AI-аналізатор замаху й тренер
Рахунок наживо й ігри з друзями
Понад 40 000 гольф-полів
Турніри', 'GPS distances and rangefinder
Digital scorecard and handicap
Game stats
AI swing analyzer and coach
Live scoring and games with friends
40,000+ golf courses
Tournaments', 'Гольфісти-аматори будь-якого рівня, які хочуть грати краще й змагатися з друзями.', 'Amateur golfers of any level who want to play better and compete with friends.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
