-- Blast Motion — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'blastmotion.com' OR LOWER(`name`) = LOWER('Blast Motion'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Blast Motion', NULL, 'https://blastmotion.com', NULL, NULL, 'Датчик для біти чи ключки з застосунком: миттєво вимірює траєкторію, швидкість і таймінг замаху, автоматично нарізає відео з показниками й пропонує вправи та цілі. Для бейсболу, софтболу й гольфу; є рішення для команд.', 'A sensor for your bat or club with an app: it instantly measures swing path, speed and timing, auto-clips video with overlaid metrics and offers drills and goals. For baseball, softball and golf, with team solutions.', 'Blast Motion перетворює будь-яку біту чи ключку на розумний тренажер. Невеликий датчик кріпиться до спорядження й синхронізується з телефоном, миттєво передаючи точні дані про замах. У бейсболі й софтболі він відстежує траєкторію біти, її швидкість, час до контакту, кут атаки тощо, у гольфі — швидкість ключки, темп, обертання лицьової частини та показники патингу. Застосунок автоматично вирізає відео кожного замаху з накладеними показниками, пропонує вправи, тренувальні цілі й відстежує прогрес, допомагаючи швидше вибудувати правильну техніку. Для тренерів і команд є відео, показники, оцінювання, анотації й голосові підказки, контроль виконання тренувань гравцями, власні тести навичок і змагання, а також об''єктивні дані для рекрутингу. Набір включає датчик, кріплення й місяць підписки.', 'Blast Motion turns any bat or club into a smart training tool. A small sensor attaches to your equipment and syncs to your phone, delivering accurate swing data instantly. In baseball and softball it tracks swing path, bat speed, time to contact, attack angle and more; in golf it tracks club speed, tempo, face rotation and putting metrics. The app auto-clips video of every swing with overlaid metrics, offers drills and training goals and tracks progress, helping you build better mechanics faster. Coaches and teams get video, metrics, assessments, annotation and voice announcements, verification that players are training, custom skills tests and competitions, and objective data for recruiting. Each kit includes the sensor, an attachment and one month of membership.', 'Датчик замаху для біти чи ключки
Траєкторія, швидкість і таймінг замаху
Відео замахів із накладеними показниками
Вправи, цілі й відстеження прогресу
Показники патингу в гольфі
Інструменти для тренерів і команд
Дані для рекрутингу', 'Swing sensor for bat or club
Swing path, speed and timing
Swing video with overlaid metrics
Drills, goals and progress tracking
Golf putting metrics
Tools for coaches and teams
Data for recruiting', 'Бейсболісти, софтболісти й гольфісти, їхні тренери та команди.', 'Baseball, softball and golf players, their coaches and teams.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
