-- Dartfish — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'dartfish.com' OR LOWER(`name`) = LOWER('Dartfish'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Dartfish', NULL, 'https://dartfish.com', NULL, NULL, 'Рішення для відеоаналізу в спорті: аналіз техніки руху для покращення результатів і профілактики травм, аналіз матчів у реальному часі для команд, системи відеоповтору VAR для суддівства й інструменти для фахівців із реабілітації.', 'Sports video analysis solutions: motion analysis to improve performance and prevent injuries, live game analysis for teams, VAR video replay systems for officiating, and tools for rehabilitation specialists.', 'Dartfish створює технології для підвищення спортивних результатів, які допомагають тренерам, командам і спортсменам. Модуль аналізу руху дає змогу детально розбирати техніку, щоб покращувати результати й запобігати травмам. Аналіз матчів допомагає розуміти й покращувати гру команди та окремих гравців, зокрема в режимі реального часу. Окремий напрям — системи відеоповтору VAR: для футболу, для інших командних видів спорту, для видів спорту з суддівським оцінюванням, а також автономна система повторів, яка працює без оператора. Для медичних фахівців є інструменти, що допомагають наочно пояснювати пацієнтам їхній стан і приділяти кожному індивідуальну увагу. Рішення використовують у футболі, бейсболі й софтболі, тенісі, легкій атлетиці, хокеї, баскетболі, плаванні, гандболі, а також персональні тренери.', 'Dartfish builds sports performance technology that helps coaches, teams and athletes. Motion analysis lets you break down technique in detail to improve performance and prevent injuries. Game analysis helps understand and enhance team and player performance, including live. A separate line covers VAR video replay systems: for football, for other team sports, for judged sports, and a self-operating replay system that runs without an operator. For healthcare professionals there are tools that help explain a patient''s condition visually and give each patient individual attention. The solutions are used in football, baseball and softball, tennis, track and field, ice hockey, basketball, swimming, handball and by personal trainers.', 'Аналіз техніки руху
Профілактика травм
Аналіз матчів у реальному часі
Системи відеоповтору VAR для суддівства
