SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hawkindynamics.com' OR LOWER(`name`) = LOWER('Hawkin Dynamics'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hawkin Dynamics', NULL, 'https://hawkindynamics.com', NULL, NULL, 'Бездротові силові платформи й динамометр із програмою для тренерів, медиків і спортсменів: точні, повторювані дані про стрибки й силу, які допомагають ухвалювати рішення щодо тренувань, відновлення й результатів.', 'Wireless force plates and a dynamometer with software for coaches, clinicians and athletes: accurate, repeatable jump and strength data that support decisions about training, recovery and performance.', 'Hawkin Dynamics допомагає тренерам, клінічним фахівцям і спортсменам ухвалювати кращі рішення на основі чітких і практичних даних. У лінійці — подвійні бездротові силові платформи, силова платформа Foundation і динамометр TruStrength для вимірювання сили, а також програма Hawkin, яка перетворює складні показники на інструменти для покращення тренувань, контролю відновлення й розкриття потенціалу. Продукти точні, повторювані й ретельно перевірені, тож на отримані дані можна покладатися; їх використали в численних опублікованих дослідженнях. Компанія спрощує робочі процеси, навчає клієнтів і допомагає їм отримувати користь від даних. Нові функції — парний режим TruStrength і табло результатів Hawkin Scoreboard 2.0. Обладнанням користуються тисячі організацій у більш ніж сотні країн.', 'Hawkin Dynamics helps coaches, clinicians and athletes make better decisions with clear, actionable data. The lineup includes Dual Wireless Force Plates, the Foundation Force Plate and the TruStrength dynamometer for strength testing, plus Hawkin software that turns complex performance insights into tools that elevate training, guide recovery and unlock potential. The products are accurate, repeatable and rigorously validated, so you can trust the data, and they have been used in many published studies. The company simplifies workflows, educates customers and helps them get value from data. New features include Paired TruStrength Mode and Hawkin Scoreboard 2.0. Thousands of organizations in over a hundred countries use the equipment.', 'Бездротові силові платформи
Динамометр TruStrength
Програма для аналізу тестів
Дані для рішень щодо тренувань і відновлення
Табло результатів Scoreboard
Перевірена точність вимірювань', 'Wireless force plates
TruStrength dynamometer
Test analysis software
Data for training and recovery decisions
Hawkin Scoreboard results display
Validated measurement accuracy', 'Тренери з фізпідготовки, фізіотерапевти, спортивні науковці й команди.', 'Strength coaches, physiotherapists, sport scientists and teams.', 'web,mobile', 'course', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
