-- K-Motion — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'k-motion.com' OR LOWER(`name`) = LOWER('K-Motion'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'K-Motion', NULL, 'https://k-motion.com', NULL, NULL, 'Система 3D-аналізу руху з біологічним зворотним зв''язком для гольфу, бейсболу й фітнесу: датчики на тілі вимірюють, як працюють сегменти тіла під час замаху, а тренер використовує ці дані для навчання й тренувань.', 'A 3D motion analysis and biofeedback system for golf, baseball and fitness: body-worn sensors measure how body segments work during the swing, and coaches use the data for teaching and training.', 'K-Motion допомагає будувати кращих спортсменів через кращий рух. Це система навчання руху з 3D-аналізом і біологічним зворотним зв''язком: вона вимірює, як окремі сегменти тіла взаємодіють між собою під час замаху, бо такі швидкі рухи важко точно оцінити на око. Тренери отримують об''єктивні кінематичні дані, на основі яких оцінюють, навчають і тренують клієнтів, а спортсмени — зрозумілі відповіді, що змінити. Для гольфу є рішення K-Coach для тренерів і K-Player для гравців, для бейсболу — K-Baseball, також є фітнес-версії. Системою користуються провідні тренери з гольфу й бейсбольні клуби; компанія є партнером Baltimore Orioles з розвитку гравців. Можна знайти тренера, який працює з K-Motion, або замовити демонстрацію.', 'K-Motion builds better athletes through better movement. It is a human motion learning system with 3D analysis and biofeedback: it measures how body segments interact during the swing, since such fast motion is hard to judge accurately by eye. Coaches get objective kinematic data to assess, teach and train clients, and athletes get clear answers on what to change. Golf has K-Coach for coaches and K-Player for players, baseball has K-Baseball, and there are fitness versions too. Leading golf instructors and baseball clubs use the system, and the company is a player development partner of the Baltimore Orioles. You can find a K-Motion coach or request a demo.', '3D-аналіз замаху
Біологічний зворотний зв''язок під час тренування
Кінематичні дані про роботу сегментів тіла
K-Coach для тренерів і K-Player для гравців
K-Baseball для бейсболу
Фітнес-версії системи
Пошук сертифікованого тренера', '3D swing analysis
Biofeedback during training
Kinematic data on body segments
K-Coach for coaches and K-Player for players
K-Baseball for baseball
Fitness versions
Finding a certified coach', 'Тренери з гольфу й бейсболу, спортсмени, академії та клуби.', 'Golf and baseball coaches, athletes, academies and clubs.', 'mobile,desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
