-- KINVENT — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kinvent.com' OR LOWER(`name`) = LOWER('KINVENT'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'KINVENT', NULL, 'https://kinvent.com', NULL, NULL, 'Підключені датчики для реабілітації й спорту: у реальному часі вимірюють силу, баланс і рухливість, допомагають фахівцям об''єктивно оцінювати стан, персоналізувати тренування, залучати пацієнтів і стежити за прогресом.', 'Connected sensors for rehab and sport: they measure strength, balance and mobility in real time, helping professionals assess objectively, personalize training, engage patients and track progress.', 'Kinvent розробляє підключені пристрої, які дають надійні дані про силу, баланс і рухливість у реальному часі. Рішення допомагають медичним і спортивним фахівцям проводити об''єктивні оцінки, ефективніше залучати пацієнтів і оптимізувати кожен етап реабілітації та підготовки. Сильна сторона компанії — біомеханічні рішення для спорту, реабілітації й наукових досліджень: система посилює експертизу фахівця аналізом у реальному часі, персоналізованими тренуваннями й супроводом пацієнтів. Для фізичних терапевтів Kinvent дає об''єктивні оцінки й відстеження прогресу, щоб покращувати результати реабілітації. Для спортивної підготовки — точні дані про силу, баланс і рухливість для оптимізації тренувань. Для лікарів — надійні біомеханічні дані для точної діагностики й персоналізованих планів лікування. Датчики працюють разом із мобільним застосунком і дають біологічний зворотний зв''язок.', 'Kinvent develops connected devices that deliver reliable real-time data on strength, balance and mobility. The solutions help healthcare and sports professionals make objective assessments, engage patients more effectively and optimize every step of rehabilitation and performance. The company specializes in biomechanical solutions for performance, rehabilitation and scientific research: the system enhances professional expertise with real-time analysis, personalized training and patient follow-up. For physical therapists, Kinvent offers objective assessments and progress tracking to improve rehab outcomes. For sports performance, it provides precise strength, balance and mobility data to optimize training. For physicians, it offers reliable biomechanical insights for accurate diagnosis and personalized treatment plans. The sensors work with a mobile app and provide biofeedback.', 'Вимірювання сили, балансу й рухливості
Дані в реальному часі
Біологічний зворотний зв''язок
Об''єктивна оцінка стану
Персоналізовані тренування
Відстеження прогресу пацієнтів і спортсменів', 'Strength, balance and mobility measurement
Real-time data
Biofeedback
Objective assessments
Personalized training
Patient and athlete progress tracking', 'Фізичні терапевти, лікарі, тренери з фізпідготовки й дослідники.', 'Physical therapists, physicians, strength coaches and researchers.', 'mobile', 'course', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
