INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Noah Basketball', NULL, 'https://noahbasketball.com', NULL, NULL, 'Система аналізу баскетбольного кидка: фіксує ключові параметри кожного кидка, дає миттєву голосову підказку, показує дані в реальному часі, виявляє звички у кидку й допомагає виробити м''язову пам''ять. Працює в залі, на подвір''ї й навіть удома.', 'A basketball shot analysis system: it captures key metrics of every shot, gives instant verbal feedback, shows real-time data, identifies shooting tendencies and helps build muscle memory. Works in the gym, the driveway or even at home.', 'Noah Basketball допомагає знайти ідеальний кидок — у спортзалі, на домашньому майданчику чи навіть у вітальні. Система фіксує й аналізує ключові параметри кидка, щоб гравці влучали частіше, а команди вигравали більше. Вона відстежує кидки, одразу дає голосовий відгук про кожну спробу, показує дані в реальному часі, допомагає виявити схильності й типові відхилення у кидку, виробити стабільну м''язову пам''ять і відстежувати показники в іграх. Тренери професійних команд після кожної гри переглядають кидки гравців, щоб помітити негативні тенденції й одразу почати з ними працювати. Систему використовують команди NBA, університетські й шкільні програми.', 'Noah Basketball provides tools for finding the perfect shot, whether in the gym, the driveway or the living room. The system captures and analyzes key shooting metrics so players make more shots and teams win more games. It offers advanced shot tracking, instant verbal feedback on every attempt, real-time data, identification of shooting tendencies, help building consistent muscle memory and tracking of your games. Pro coaches review players'' shots after every game to spot negative trends and address them right away. The system is used by NBA teams and college and high school programs.', 'Відстеження параметрів кожного кидка
Миттєвий голосовий відгук
Дані в реальному часі
Виявлення звичок і відхилень у кидку
Формування м''язової пам''яті
Відстеження кидків в іграх', 'Tracking metrics of every shot
Instant verbal feedback
Real-time data
Identifying shooting tendencies
Building muscle memory
Game shot tracking', 'Баскетболісти, тренери професійних, університетських і шкільних команд.', 'Basketball players and coaches of pro, college and high school teams.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
