-- Playermaker — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'playermaker.com' OR LOWER(`name`) = LOWER('Playermaker'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Playermaker', NULL, 'https://playermaker.com', NULL, NULL, 'Датчик на бутсу для футболістів: точно фіксує кожен крок, спринт і дотик до м''яча, окремо аналізує ліву й праву ногу, працює на іграх і тренуваннях, показує персональні дані в застосунку, а тренерам дає панель усієї команди.', 'A boot-mounted sensor for footballers: it captures every step, sprint and ball touch, analyzes left and right foot separately, works in games and training, shows personal data in an app and gives coaches a team dashboard.', 'Playermaker — носимий трекер для футболу, який кріпиться на ногу й перетворює кожен дотик до м''яча та кожен рух на зрозумілі дані для реального покращення гри. Датчик точно відстежує рухи в реальному часі, окремо аналізує роботу лівої й правої ноги, допомагаючи стати впевненим на обидві ноги. Дані збираються як на тренуваннях, так і в справжніх матчах, тож прогрес вимірюється там, де це найважливіше. У застосунку результати представлені наочно з персональними висновками й цілями, а показники можна порівняти з гравцями академій і професіоналами для мотивації. Тренери мають доступ до панелі з даними всіх гравців, щоб будувати індивідуальний розвиток. Технологію використовують клуби й федерації по всьому світу.', 'Playermaker is a foot-mounted wearable football tracker that turns every ball touch and every move into actionable insights for lasting improvement. The sensor tracks movement in real time with high accuracy and analyzes each foot separately, helping players build two-footed confidence and control. Data is captured in both training sessions and real matches, so progress is measured where it matters most. The app presents performance with personalized insights and goals, and you can compare your stats to academy and pro players for motivation. Coaches get a dashboard with the data of every player to guide tailored development. Clubs and federations around the world use the technology.', 'Відстеження кроків, спринтів і дотиків до м''яча
Аналіз лівої й правої ноги
Режими для тренувань і матчів
Персональні висновки й цілі в застосунку
Порівняння з гравцями академій і профі
Панель тренера для всієї команди', 'Tracking steps, sprints and ball touches
Left and right foot analysis
Game-day and practice modes
Personal insights and goals in the app
Benchmarks against academy and pro players
Coach dashboard for the whole team', 'Футболісти будь-якого рівня, юні гравці, тренери, клуби й федерації.', 'Footballers of every level, young players, coaches, clubs and federations.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
