INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Playermaker is a foot-mounted wearable football tracker that turns every ball touch and every move into actionable insights for lasting improvement. The sensor tracks movement in real time with high accuracy and analyzes each foot separately, helping players build two-footed confidence and control. Data is captured in both training sessions and real matches, so progress is measured where it matters most. The app presents performance with personalized insights and goals, and you can compare your stats to academy and pro players for motivation. Coaches get a dashboard with the data of every player to guide tailored development. Clubs and federations around the world use the technology.', 'manual' FROM DUAL WHERE @new = 1;
