SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'rapsodo.com' OR LOWER(`name`) = LOWER('Rapsodo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Rapsodo', NULL, 'https://rapsodo.com', NULL, NULL, 'Портативні лаунч-монітори й гольф-симулятори, а також пристрої для аналізу ударів і подач у бейсболі та софтболі: точні дані про політ м''яча допомагають точно знати дистанції, тренуватися цілеспрямовано й швидше прогресувати.', 'Portable launch monitors and golf simulators, plus devices that analyze hitting and pitching in baseball and softball: accurate ball flight data helps you dial in distances, practice with purpose and improve faster.', 'Rapsodo створює доступні, портативні й прості у використанні технології для тренувань у гольфі, бейсболі й софтболі на основі даних. Мобільні лаунч-монітори для гольфу вимірюють параметри удару й польоту м''яча, допомагають точно знати свої дистанції, швидше прогресувати й отримувати задоволення від тренувань — для новачків і досвідчених гравців. Найновіша модель MLM2XPRO — найшвидший і найдосконаліший лаунч-монітор та гольф-симулятор компанії; MLM2PRO також працює як симулятор і може продаватися разом із програмою швидкісних тренувань TheStack. Для бейсболу й софтболу є пристрій, який аналізує і відбивання, і подачі. Продукти продаються в офіційному інтернет-магазині, часто зі знижками.', 'Rapsodo builds affordable, portable, easy-to-use technology for data-driven training in golf, baseball and softball. Its mobile golf launch monitors measure shot and ball flight data, helping you dial in distances, improve faster and enjoy practice, whether you are a beginner or a seasoned player. The newest MLM2XPRO is the company''s fastest and most advanced launch monitor and golf simulator; the MLM2PRO also works as a simulator and can come bundled with TheStack speed training program. For baseball and softball there is a device that analyzes both hitting and pitching. Products are sold through the official online store, often on sale.', 'Портативні лаунч-монітори для гольфу
Гольф-симулятори для дому
Дані про удар і політ м''яча
Пристрій для аналізу відбивання й подач
Програма швидкісних тренувань TheStack
Для новачків і професіоналів', 'Portable golf launch monitors
Home golf simulators
Shot and ball flight data
Hitting and pitching analysis device
TheStack speed training program
For beginners and pros', 'Гольфісти, бейсболісти й софтболісти будь-якого рівня та їхні тренери.', 'Golf, baseball and softball players of every level and their coaches.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
