SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'runeasi.ai' OR LOWER(`name`) = LOWER('Runeasi'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Runeasi', NULL, 'https://runeasi.ai', NULL, NULL, 'Інструмент для фізіотерапевтів і тренерів для аналізу бігу й стрибків: датчик налаштовується менш ніж за хвилину, вимірює навантаження, стабільність, потужність, реактивність і симетрію будь-де та одразу формує звіт для клієнта.', 'A running and jump analysis tool for physios and coaches: the sensor sets up in under a minute, measures load, stability, power, reactivity and symmetry anywhere and instantly produces a client-ready report.', 'Runeasi — платформа для фізіотерапевтів і тренерів, яка дає об''єктивні дані для реабілітації, профілактики травм і покращення результатів бігунів. Візуальна оцінка руху не показує, як клієнт реагує на навантаження, ручні звіти забирають час, а клієнти втрачають мотивацію, коли не бачать прогресу. Runeasi вирішує ці проблеми: один інструмент для аналізу бігу й стрибків вимірює навантаження, стабільність, потужність, реактивність і симетрію. Показники перевірені порівнянням із силовими платформами й 3D-захопленням руху. Налаштування займає менше хвилини, а тестувати можна будь-де — на біговій доріжці, майданчику, стадіоні чи стежці. Миттєві звіти підвищують мотивацію й дисципліну клієнтів, система пропонує вправи на основі даних і дає дані в реальному часі для перенавчання техніки бігу. Звіти можна використовувати й для просування в соцмережах. Доступна демонстрація.', 'Runeasi is a platform that gives physios and coaches objective data to guide rehab, injury prevention and performance for runners. Visual assessment doesn''t show how clients respond to load, manual reporting takes time, and clients lose motivation when they can''t see improvement. Runeasi addresses this with one tool for running and jumping that measures load, stability, power, reactivity and symmetry. The metrics are validated against force plates and 3D motion capture. Setup takes under 60 seconds, and you can test anywhere: treadmill, court, track or trail. Instant reports boost client motivation and adherence, the system suggests data-driven exercises and provides real-time data for gait retraining. Reports also work as marketing content for social media. Demos are available.', 'Аналіз бігу й стрибків
Навантаження, стабільність, потужність і симетрія
Налаштування менш ніж за хвилину
Тестування будь-де
Миттєві звіти для клієнтів
Рекомендації вправ на основі даних
Дані в реальному часі для корекції техніки', 'Running and jump analysis
Load, stability, power and symmetry
Setup in under a minute
Test anywhere
Instant client reports
Data-driven exercise guidance
Real-time data for gait retraining', 'Фізіотерапевти, реабілітологи й тренери, які працюють із бігунами.', 'Physiotherapists, rehab specialists and coaches working with runners.', 'mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
