SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'theiamarkerless.com' OR LOWER(`name`) = LOWER('Theia'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Theia', NULL, 'https://theiamarkerless.com', NULL, NULL, 'Безмаркерне захоплення руху: штучний інтелект відстежує 124 точки тіла на звичайному відео з точністю до сантиметра без датчиків і маркерів, тож біомеханічні дані можна збирати не лише в лабораторії, а й на тренуваннях і змаганнях.', 'Markerless motion capture: AI tracks 124 body keypoints from ordinary video with centimeter accuracy and no sensors or markers, so biomechanics data can be collected not only in the lab but in training and competition.', 'Theia — система безмаркерного захоплення руху, яка спрощує біомеханічні дослідження й аналіз руху людини. Замість маркерів і датчиків глибока нейромережа відстежує 124 ключові точки тіла з точністю до сантиметра й кількох градусів, а готові до використання дані з''являються за кілька хвилин. Це дозволяє суттєво заощадити на обладнанні й підвищити ефективність роботи. Оскільки на спортсмена нічого не потрібно чіпляти, якісні дані можна збирати в природних умовах — на полі, на доріжці чи на майданчику, а не тільки в лабораторії. Систему використовують університетські дослідники біомеханіки, спортивні наукові відділи, виробники спортивного одягу й взуття. Продукт Theia Mode можна спробувати або замовити демонстрацію.', 'Theia is a markerless motion capture system that streamlines biomechanics research and human movement analysis. Instead of markers and sensors, deep-learning AI tracks 124 keypoints on the body with under 1 cm and 3 degrees of precision, and actionable data is ready in minutes. This brings significant cost savings and higher operational efficiency. Because nothing needs to be attached to the athlete, high-fidelity data can be collected in natural settings, on the field, track or court, not only in the lab. It is used by university biomechanics researchers, sport science departments and footwear and apparel makers. You can try Theia Mode or book a demo.', 'Захоплення руху без маркерів і датчиків
Відстеження 124 точок тіла
Висока точність вимірювань
Дані готові за кілька хвилин
Збір даних у реальних спортивних умовах
Для досліджень, спорту й розробки екіпірування', 'Motion capture without markers or sensors
Tracking of 124 body keypoints
High measurement precision
Data ready in minutes
Data collection in real sport settings
For research, sport and apparel development', 'Дослідники біомеханіки, спортивні наукові відділи, команди й виробники спортивного одягу та взуття.', 'Biomechanics researchers, sport science departments, teams, and apparel and footwear makers.', 'desktop', 'course', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
