SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'uplift.ai' OR LOWER(`name`) = LOWER('Uplift'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Uplift', NULL, 'https://uplift.ai', NULL, NULL, 'AI-аналіз рухів спортсменів і 3D-захоплення руху за допомогою смартфона: інструмент біомеханічної оцінки Signals перетворює дані на практичні поради, а окремі рішення є для команд і для спортивних трансляцій.', 'AI movement analysis and 3D motion capture with a smartphone: the Signals biomechanics evaluation tool turns data into actionable advice, with separate solutions for teams and for sports broadcasts.', 'Uplift Labs допомагає оптимізувати руховий потенціал людини за допомогою аналізу на основі штучного інтелекту. Новий інструмент біомеханічної оцінки Signals перетворює дані про рух на зрозумілі й практичні висновки. Для тренерів і спортсменів Uplift аналізує рухи, дає глибокі інсайти й персональні рекомендації для покращення результатів. Uplift Capture для команд і організацій поєднує точне 3D-захоплення руху, AI-аналіз, кінематику, ключові показники й звіти. Uplift Vision для мовників і стримерів показує глядачам цікаві дані про рухи спортсменів і підвищує залученість уболівальників. Технологія перетворює iPhone на біомеханічний інструмент і допомагає захищати юних спортсменів від травм; її використовують і бейсбольні скаути. Є 14-денний пробний період і демонстрація.', 'Uplift Labs helps optimize human movement performance with AI-powered analysis. Its new biomechanics evaluation tool, Signals, translates movement data into clear, actionable insights. For coaches and athletes, Uplift analyzes movement and delivers deep insights and personalized recommendations to improve performance. Uplift Capture for teams and organizations combines precise 3D capture, AI movement analysis, kinematics, key metrics and reporting. Uplift Vision for broadcasters and streamers surfaces athlete movement insights to enrich the viewing experience and drive fan engagement. The technology turns iPhones into biomechanical tools and helps protect young athletes from injury; baseball scouts use it too. A 14-day trial and demos are available.', 'AI-аналіз рухів спортсменів
3D-захоплення руху зі смартфона
Інструмент біомеханічної оцінки Signals
Персональні рекомендації
Кінематика, ключові показники й звіти для команд
Дані про рухи для спортивних трансляцій', 'AI movement analysis for athletes
3D motion capture from a smartphone
Signals biomechanics evaluation tool
Personalized recommendations
Kinematics, key metrics and reports for teams
Movement data for broadcasts', 'Тренери, спортсмени, команди, спортивні організації й мовники.', 'Coaches, athletes, teams, sports organizations and broadcasters.', 'mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
